            modelBuilder.Entity("Unifesspa.UniPlus.Configuracao.Domain.Entities.LocalOferta", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid")
                        .HasColumnName("id");

                    b.Property<Guid?>("CampusResponsavelId")
                        .HasColumnType("uuid")
                        .HasColumnName("campus_responsavel_id");

                    b.Property<string>("CidadeCodigoIbge")
                        .IsRequired()
                        .HasMaxLength(7)
                        .HasColumnType("character(7)")
                        .HasColumnName("cidade_codigo_ibge")
                        .IsFixedLength();

                    b.Property<DateTimeOffset?>("CidadeDisplayAtualizadoEm")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("cidade_display_atualizado_em");

                    b.Property<string>("CidadeNome")
                        .IsRequired()
                        .HasMaxLength(150)
                        .HasColumnType("character varying(150)")
                        .HasColumnName("cidade_nome");

                    b.Property<string>("CidadeOrigem")
                        .HasMaxLength(50)
                        .HasColumnType("character varying(50)")
                        .HasColumnName("cidade_origem");

                    b.Property<string>("CidadeUf")
                        .IsRequired()
                        .HasMaxLength(2)
                        .HasColumnType("character(2)")
                        .HasColumnName("cidade_uf")
                        .IsFixedLength();

                    b.Property<string>("CodigoEmec")
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("codigo_emec");

                    b.Property<DateTimeOffset>("CreatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at")
                        .HasComment("Data e hora de criação do registro.");

                    b.Property<string>("CreatedBy")
                        .HasMaxLength(255)
                        .HasColumnType("character varying(255)")
                        .HasColumnName("created_by")
                        .HasComment("Identificador do responsável pela criação, quando disponível.");

                    b.Property<DateTimeOffset?>("DeletedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("deleted_at")
                        .HasComment("Data e hora da exclusão lógica, quando houver.");

                    b.Property<string>("DeletedBy")
                        .HasColumnType("text")
                        .HasColumnName("deleted_by")
                        .HasComment("Identificador do responsável pela exclusão lógica, quando disponível.");

                    b.Property<bool>("IsDeleted")
                        .HasColumnType("boolean")
                        .HasColumnName("is_deleted")
                        .HasComment("Indica se o registro foi excluído logicamente.");

                    b.Property<string>("Tipo")
                        .IsRequired()
                        .HasMaxLength(30)
                        .HasColumnType("character varying(30)")
                        .HasColumnName("tipo")
                        .HasComment("Códigos: CAMPUS_SEDE, CAMPUS_FORA_DE_SEDE, CURSO_FORA_DE_SEDE, POLO_DE_EDUCACAO_A_DISTANCIA, CONVENIO_DE_INTERIORIZACAO, OUTRO.");

                    b.Property<DateTimeOffset?>("UpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at")
                        .HasComment("Data e hora da última alteração, quando houver.");

                    b.Property<string>("UpdatedBy")
                        .HasMaxLength(255)
                        .HasColumnType("character varying(255)")
                        .HasColumnName("updated_by")
                        .HasComment("Identificador do responsável pela última alteração, quando disponível.");

                    b.HasKey("Id")
                        .HasName("pk_locais_de_oferta");

                    b.HasIndex("CampusResponsavelId")
                        .HasDatabaseName("ix_locais_de_oferta_campus_responsavel_id");

                    b.HasIndex("CidadeCodigoIbge")
                        .HasDatabaseName("ix_locais_de_oferta_cidade_codigo_ibge");

                    b.ToTable("locais_de_oferta", "configuracao", t =>
                        {
                            t.HasCheckConstraint("ck_locais_de_oferta_endereco_cidade_coerente", "endereco_cidade_codigo_ibge IS NULL OR cidade_codigo_ibge IS NULL OR (endereco_cidade_codigo_ibge = cidade_codigo_ibge AND endereco_cidade_uf IS NOT NULL AND cidade_uf IS NOT NULL AND endereco_cidade_uf = cidade_uf)");

                            t.HasCheckConstraint("ck_locais_de_oferta_endereco_completo", "(endereco_cep IS NULL AND endereco_cidade_codigo_ibge IS NULL AND endereco_cidade_nome IS NULL AND endereco_cidade_uf IS NULL AND endereco_nivel_resolucao IS NULL AND endereco_origem IS NULL AND endereco_logradouro IS NULL AND endereco_numero IS NULL AND endereco_complemento IS NULL AND endereco_bairro IS NULL AND endereco_distrito IS NULL AND endereco_latitude IS NULL AND endereco_longitude IS NULL) OR (endereco_cep IS NOT NULL AND endereco_cidade_codigo_ibge IS NOT NULL AND endereco_cidade_nome IS NOT NULL AND endereco_cidade_uf IS NOT NULL AND endereco_nivel_resolucao IS NOT NULL AND endereco_origem IS NOT NULL)");

                            t.HasCheckConstraint("ck_locais_de_oferta_tipo", "tipo IN ('CAMPUS_SEDE', 'CAMPUS_FORA_DE_SEDE', 'CURSO_FORA_DE_SEDE', 'POLO_DE_EDUCACAO_A_DISTANCIA', 'CONVENIO_DE_INTERIORIZACAO', 'OUTRO')");
                        });
                });

            modelBuilder.Entity("Unifesspa.UniPlus.Configuracao.Domain.Entities.ManifestacaoDaProtecaoDoCatalogo", b =>
                {
                    b.Property<Guid>("Id")
                        .HasColumnType("uuid")
                        .HasColumnName("id");

                    b.Property<int>("Ciclo")
                        .HasColumnType("integer")
                        .HasColumnName("ciclo");

                    b.Property<DateTimeOffset>("Instante")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("instante");

                    b.Property<long>("OrdemDeRegistro")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("bigint")
                        .HasColumnName("ordem_de_registro");

                    NpgsqlPropertyBuilderExtensions.UseIdentityAlwaysColumn(b.Property<long>("OrdemDeRegistro"));

                    b.Property<string>("Parecer")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("parecer");

                    b.Property<Guid?>("SubstituiId")
                        .HasColumnType("uuid")
                        .HasColumnName("substitui_id");

                    b.Property<string>("Texto")
                        .HasMaxLength(2000)
                        .HasColumnType("character varying(2000)")
                        .HasColumnName("texto");

                    b.Property<string>("_autorContaId")
                        .IsRequired()
                        .HasMaxLength(255)
                        .HasColumnType("character varying(255)")
                        .HasColumnName("autor_conta_id");

                    b.Property<string>("_autorEmissor")
                        .IsRequired()
                        .HasMaxLength(255)
                        .HasColumnType("character varying(255)")
                        .HasColumnName("autor_emissor");

                    b.Property<string>("_autorNome")
                        .HasMaxLength(255)
                        .HasColumnType("character varying(255)")
                        .HasColumnName("autor_nome");

                    b.Property<string>("_cadastro")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("cadastro");

                    b.Property<Guid>("_itemId")
                        .HasColumnType("uuid")
                        .HasColumnName("item_id");

                    b.HasKey("Id")
                        .HasName("pk_manifestacoes_da_protecao");

                    b.HasIndex("OrdemDeRegistro")
                        .IsUnique()
                        .HasDatabaseName("ux_manifestacoes_da_protecao_ordem_de_registro");

                    b.HasIndex("SubstituiId")
                        .IsUnique()
                        .HasDatabaseName("ux_manifestacoes_da_protecao_substitui");

                    b.HasIndex("_cadastro", "_itemId", "Ciclo", "Instante")
                        .HasDatabaseName("ix_manifestacoes_da_protecao_item_ciclo");

                    b.HasIndex("_cadastro", "_itemId", "Ciclo", "_autorEmissor", "_autorContaId")
                        .IsUnique()
                        .HasDatabaseName("ux_manifestacoes_da_protecao_inicial_do_autor")
                        .HasFilter("substitui_id IS NULL");

                    b.ToTable("manifestacoes_da_protecao", "configuracao", t =>
                        {
                            t.HasCheckConstraint("ck_manifestacoes_da_protecao_cadastro", "cadastro IN ('TIPO_DOCUMENTO', 'DADO_DO_CANDIDATO')");

                            t.HasCheckConstraint("ck_manifestacoes_da_protecao_ciclo_positivo", "ciclo >= 1");

                            t.HasCheckConstraint("ck_manifestacoes_da_protecao_parecer", "parecer IN ('RECOMENDA_APROVACAO', 'RECOMENDA_AJUSTE', 'RECOMENDA_NAO_USO')");

                            t.HasCheckConstraint("ck_manifestacoes_da_protecao_substitui_outra", "substitui_id IS NULL OR substitui_id <> id");

                            t.HasCheckConstraint("ck_manifestacoes_da_protecao_texto_no_desfavoravel", "parecer = 'RECOMENDA_APROVACAO' OR texto IS NOT NULL");
                        });
                });

