            modelBuilder.Entity("Unifesspa.UniPlus.Configuracao.Domain.Entities.TipoEtapa", b =>
                {
                    b.Property<Guid>("Id")
                        .HasColumnType("uuid")
                        .HasColumnName("id");

                    b.Property<bool>("AdmiteEliminacao")
                        .HasColumnType("boolean")
                        .HasColumnName("admite_eliminacao");

                    b.Property<bool>("AdmitePontuacao")
                        .HasColumnType("boolean")
                        .HasColumnName("admite_pontuacao");

                    b.Property<bool>("Ativo")
                        .HasColumnType("boolean")
                        .HasColumnName("ativo");

                    b.Property<string>("Codigo")
                        .IsRequired()
                        .HasMaxLength(80)
                        .HasColumnType("character varying(80)")
                        .HasColumnName("codigo");

                    b.Property<DateTimeOffset>("CreatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at")
                        .HasComment("Data e hora de criação do registro.");

                    b.Property<string>("CreatedBy")
                        .HasMaxLength(255)
                        .HasColumnType("character varying(255)")
                        .HasColumnName("created_by")
                        .HasComment("Identificador do responsável pela criação, quando disponível.");

                    b.Property<string>("Descricao")
                        .HasMaxLength(1000)
                        .HasColumnType("character varying(1000)")
                        .HasColumnName("descricao");

                    b.Property<bool>("ExigeCorrecaoIndependente")
                        .HasColumnType("boolean")
                        .HasColumnName("exige_correcao_independente");

                    b.Property<string>("Nome")
                        .IsRequired()
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("nome");

                    b.Property<bool>("NotaDeOrigemNoEnem")
                        .HasColumnType("boolean")
                        .HasColumnName("nota_de_origem_no_enem")
                        .HasComment("Nota das etapas deste tipo vem do ENEM; definido só pela carga do cadastro, nunca pela API.");

                    b.Property<DateTimeOffset?>("UpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at")
                        .HasComment("Data e hora da última alteração, quando houver.");

                    b.Property<string>("UpdatedBy")
                        .HasMaxLength(255)
                        .HasColumnType("character varying(255)")
                        .HasColumnName("updated_by")
                        .HasComment("Identificador do responsável pela última alteração, quando disponível.");

                    b.Property<uint>("Version")
                        .IsConcurrencyToken()
                        .ValueGeneratedOnAddOrUpdate()
                        .HasColumnType("xid")
                        .HasColumnName("xmin")
                        .HasComment("Versão da linha mantida pelo PostgreSQL para controle de alterações concorrentes.");

                    b.HasKey("Id")
                        .HasName("pk_tipos_etapa");

                    b.HasIndex("Ativo")
                        .HasDatabaseName("ix_tipos_etapa_ativo");

                    b.HasIndex("Codigo")
                        .IsUnique()
                        .HasDatabaseName("ux_tipos_etapa_codigo");

                    b.ToTable("tipos_etapa", "configuracao", t =>
                        {
                            t.HasCheckConstraint("ck_tipos_etapa_carater_admitido", "admite_pontuacao OR admite_eliminacao");

                            t.HasCheckConstraint("ck_tipos_etapa_codigo_formato", "codigo ~ '^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$'");

                            t.HasCheckConstraint("ck_tipos_etapa_correcao_independente_sem_nota_do_enem", "NOT (exige_correcao_independente AND nota_de_origem_no_enem)");

                            t.HasCheckConstraint("ck_tipos_etapa_nota_de_origem_no_enem_admite_pontuacao", "NOT nota_de_origem_no_enem OR admite_pontuacao");
                        });
                });

