            modelBuilder.Entity("Unifesspa.UniPlus.Discentes.Domain.Entities.SyncRun", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid")
                        .HasColumnName("id")
                        .HasComment("Identificador interno (UUIDv7) da execução.");

                    b.Property<DateTimeOffset>("CreatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("created_at")
                        .HasComment("Data e hora de criação do registro.");

                    b.Property<DateOnly>("DataDeReferencia")
                        .HasColumnType("date")
                        .HasColumnName("data_de_referencia")
                        .HasComment("Dia a que a execução se refere — não o instante em que rodou. Uma execução disparada de madrugada refere-se ao dia que começou.");

                    b.Property<int>("ErrorCount")
                        .HasColumnType("integer")
                        .HasColumnName("error_count")
                        .HasComment("Quantidade de itens que falharam durante o processamento.");

                    b.Property<DateTime?>("FinishedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("finished_at")
                        .HasComment("Instante de conclusão da execução — nulo enquanto o status é EM_ANDAMENTO.");

                    b.Property<int>("ProcessedItems")
                        .HasColumnType("integer")
                        .HasColumnName("processed_items")
                        .HasComment("Quantidade de itens já processados.");

                    b.Property<DateTime>("StartedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("started_at")
                        .HasComment("Instante de início da execução.");

                    b.Property<string>("Status")
                        .IsRequired()
                        .HasMaxLength(30)
                        .HasColumnType("character varying(30)")
                        .HasColumnName("status")
                        .HasComment("Situação da execução. Códigos: EM_ANDAMENTO, CONCLUIDA, PARCIAL, FALHOU.");

                    b.Property<int>("SuccessCount")
                        .HasColumnType("integer")
                        .HasColumnName("success_count")
                        .HasComment("Quantidade de itens processados com sucesso.");

                    b.Property<int>("TotalItems")
                        .HasColumnType("integer")
                        .HasColumnName("total_items")
                        .HasComment("Quantidade total de itens previstos para esta execução.");

                    b.Property<DateTimeOffset?>("UpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at")
                        .HasComment("Data e hora da última alteração, quando houver.");

                    b.HasKey("Id")
                        .HasName("pk_sincronizacoes_com_o_sigaa");

                    b.HasIndex("DataDeReferencia")
                        .HasDatabaseName("ix_sincronizacoes_com_o_sigaa_data_de_referencia");

                    b.HasIndex("StartedAt")
                        .HasDatabaseName("ix_sincronizacoes_com_o_sigaa_started_at");

                    b.ToTable("sincronizacoes_com_o_sigaa", "discentes", t =>
                        {
                            t.HasComment("Controle de execução das rotinas de sincronização de dados discentes com o SIGAA — uma linha por execução.");

                            t.HasCheckConstraint("ck_sincronizacoes_com_o_sigaa_status", "status IN ('EM_ANDAMENTO', 'CONCLUIDA', 'PARCIAL', 'FALHOU')");
                        });
                });

