                    b.Property<DateTimeOffset?>("ConfirmadoEm")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("confirmado_em");

                    b.Property<bool>("ConstouDeEnvio")
                        .HasColumnType("boolean")
                        .HasColumnName("constou_de_envio")
