                        .HasComment("Quantos cursos o candidato escolhe na inscrição (1 ou 2). Nulo = ainda não declarado.");

                    b.Property<string>("OrigemCandidatos")
                        .IsRequired()
                        .HasMaxLength(30)
                        .HasColumnType("character varying(30)")
                        .HasColumnName("origem_candidatos")
                        .HasComment("Como os candidatos chegam ao processo. Códigos: INSCRICAO_PROPRIA, IMPORTACAO_EXTERNA.");

                    b.Property<string>("Situacao")
                        .IsRequired()
                        .HasMaxLength(30)
                        .HasColumnType("character varying(30)")
                        .HasColumnName("situacao")
                        .HasComment("Situação do processo seletivo. Códigos: RASCUNHO, PUBLICADO, ENCERRADO, CANCELADO.");

                    b.Property<Guid>("UnidadeAdministradoraOrigemId")
                        .HasColumnType("uuid")
                        .HasColumnName("unidade_administradora_origem_id")
                        .HasComment("Identificador da unidade administradora no cadastro de origem, copiado na criação e mantido sem alteração.");

                    b.Property<DateTimeOffset?>("UpdatedAt")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("updated_at")
                        .HasComment("Data e hora da última alteração, quando houver.");

                    b.HasKey("Id")
                        .HasName("pk_processos_seletivos");

                    b.HasIndex("IdentificadorLegivel")
                        .IsUnique()
                        .HasDatabaseName("ux_processos_seletivos_identificador_legivel");

                    b.ToTable("processos_seletivos", "selecao", t =>
                        {
                            t.HasComment("Processos seletivos e suas configurações declaradas para a seleção de candidatos.");

                            t.HasCheckConstraint("ck_processos_seletivos_manifestacao_de_interesse", "manifestacao_de_interesse IS NULL OR manifestacao_de_interesse IN ('UMA_VEZ', 'CONFIRMA_A_CADA_CHAMADA')");

                            t.HasCheckConstraint("ck_processos_seletivos_numero_de_opcoes_de_curso", "numero_de_opcoes_de_curso IS NULL OR numero_de_opcoes_de_curso IN (1, 2)");

                            t.HasCheckConstraint("ck_processos_seletivos_origem_candidatos", "origem_candidatos IN ('INSCRICAO_PROPRIA', 'IMPORTACAO_EXTERNA')");

                            t.HasCheckConstraint("ck_processos_seletivos_situacao", "situacao IN ('RASCUNHO', 'PUBLICADO', 'ENCERRADO', 'CANCELADO')");

                            t.HasCheckConstraint("ck_processos_seletivos_tipo_processo_codigo_formato", "tipo_processo_codigo ~ '^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$'");

                            t.HasCheckConstraint("ck_processos_seletivos_unidade_administradora_cidade_completa", "(unidade_administradora_cidade_codigo_ibge IS NULL AND unidade_administradora_cidade_nome IS NULL AND unidade_administradora_cidade_uf IS NULL) OR (unidade_administradora_cidade_codigo_ibge IS NOT NULL AND unidade_administradora_cidade_nome IS NOT NULL AND unidade_administradora_cidade_uf IS NOT NULL)");
                        });
                });

