                        .HasColumnName("fase_cronograma_id")
                        .HasComment("Identificador do registro ao qual esta configuração pertence.");

                    b.Property<string>("Procedimentos")
                        .IsRequired()
                        .ValueGeneratedOnAdd()
                        .HasColumnType("jsonb")
                        .HasColumnName("procedimentos_de_recurso")
                        .HasDefaultValueSql("'[]'::jsonb")
