                        .HasMaxLength(60)
                        .HasColumnType("character varying(60)")
                        .HasColumnName("valor_codigo")
                        .HasComment("Código da opção ou município respondido, quando aplicável.");

                    b.Property<DateOnly?>("ValorData")
                        .HasColumnType("date")
                        .HasColumnName("valor_data")
                        .HasComment("Resposta de data, quando aplicável.");

                    b.Property<decimal?>("ValorNumero")
                        .HasColumnType("numeric")
                        .HasColumnName("valor_numero")
                        .HasComment("Resposta numérica, quando aplicável.");

                    b.Property<string>("ValorRotulo")
                        .HasColumnType("text")
                        .HasColumnName("valor_rotulo")
                        .HasComment("O nome que o Geo conferiu para o município de valor_codigo; nulo no rascunho e preenchido na inscrição enviada.");

                    b.Property<bool?>("ValorSimOuNao")
                        .HasColumnType("boolean")
                        .HasColumnName("valor_sim_ou_nao")
                        .HasComment("Resposta de sim ou não, quando aplicável.");

                    b.Property<string>("ValorTexto")
                        .HasColumnType("text")
                        .HasColumnName("valor_texto")
                        .HasComment("Resposta em texto livre, quando aplicável.");

                    b.HasKey("Id")
                        .HasName("pk_respostas_da_inscricao");

                    b.HasIndex("OcorrenciaId")
                        .HasDatabaseName("ix_respostas_da_inscricao_ocorrencia_id");

                    b.HasIndex("FatoCodigo", "ValorCodigo")
                        .HasDatabaseName("ix_respostas_da_inscricao_dado_codigo")
                        .HasFilter("valor_codigo IS NOT NULL");

                    b.HasIndex("FatoCodigo", "ValorData")
                        .HasDatabaseName("ix_respostas_da_inscricao_dado_data")
                        .HasFilter("valor_data IS NOT NULL");

                    b.HasIndex("FatoCodigo", "ValorNumero")
                        .HasDatabaseName("ix_respostas_da_inscricao_dado_numero")
                        .HasFilter("valor_numero IS NOT NULL");

                    b.HasIndex("FatoCodigo", "ValorSimOuNao")
                        .HasDatabaseName("ix_respostas_da_inscricao_dado_sim_ou_nao")
                        .HasFilter("valor_sim_ou_nao IS NOT NULL");

                    b.HasIndex("InscricaoId", "OcorrenciaId", "FatoCodigo", "Posicao")
                        .IsUnique()
                        .HasDatabaseName("ux_respostas_da_inscricao_valor");

                    NpgsqlIndexBuilderExtensions.AreNullsDistinct(b.HasIndex("InscricaoId", "OcorrenciaId", "FatoCodigo", "Posicao"), false);

                    b.ToTable("respostas_da_inscricao", "selecao", t =>
                        {
                            t.HasComment("Um valor respondido na inscrição, na coluna do tipo do dado, com a origem: informado pelo candidato ou calculado a partir de outra resposta.");

                            t.HasCheckConstraint("ck_respostas_da_inscricao_origem", "origem IN ('INFORMADA', 'CALCULADA')");

                            t.HasCheckConstraint("ck_respostas_da_inscricao_valor_do_tipo", "num_nonnulls(valor_sim_ou_nao, valor_numero, valor_codigo, valor_texto, valor_data, valor_cifrado) = 1 AND tipo IN ('SIM_OU_NAO', 'NUMERO', 'OPCAO', 'TEXTO', 'DATA', 'MUNICIPIO') AND (valor_cifrado IS NOT NULL OR (tipo = 'SIM_OU_NAO' AND valor_sim_ou_nao IS NOT NULL) OR (tipo = 'NUMERO' AND valor_numero IS NOT NULL) OR (tipo = 'OPCAO' AND valor_codigo IS NOT NULL) OR (tipo = 'TEXTO' AND valor_texto IS NOT NULL) OR (tipo = 'DATA' AND valor_data IS NOT NULL) OR (tipo = 'MUNICIPIO' AND valor_codigo IS NOT NULL)) AND (valor_rotulo IS NULL OR (tipo = 'MUNICIPIO' AND valor_codigo IS NOT NULL))");
                        });
                });

