                                    t.HasCheckConstraint("ck_areas_dos_pesos_do_enem_peso", "peso >= 0");
                                });

                            b1.WithOwner()
                                .HasForeignKey("PesoAreaEnemId")
                                .HasConstraintName("fk_areas_dos_pesos_do_enem_peso_por_area_do_enem");
